SELECT *, 1 AS _dup_rank FROM (SELECT bronze_id, row_hash, "id", "state", "opened", "closed", "amount", "flag", (payload ->> 'state') AS "state_raw", (payload ->> 'opened') AS "opened_raw", (payload ->> 'closed') AS "closed_raw", (payload ->> 'amount') AS "amount_raw", (payload ->> 'flag') AS "flag_raw", jsonb_strip_nulls(jsonb_build_object('id', silver.flags(CASE WHEN "id__c" IS DISTINCT FROM (payload ->> 'id') AND "id__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "id__tok" THEN 'null_token' END, CASE WHEN "id__sen" THEN 'sentinel:' || "id__c" END, CASE WHEN "id__m" IS DISTINCT FROM "id__v" AND "id__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "id__unm" THEN 'unmapped' END, CASE WHEN "id__bad" THEN 'unparseable' END, CASE WHEN "id__oor" THEN 'out_of_range' END), 'state', silver.flags(CASE WHEN "state__c" IS DISTINCT FROM (payload ->> 'state') AND "state__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "state__tok" THEN 'null_token' END, CASE WHEN "state__sen" THEN 'sentinel:' || "state__c" END, CASE WHEN "state__m" IS DISTINCT FROM "state__v" AND "state__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "state__unm" THEN 'unmapped' END, CASE WHEN "state__bad" THEN 'unparseable' END, CASE WHEN "state__oor" THEN 'out_of_range' END), 'opened', silver.flags(CASE WHEN "opened__c" IS DISTINCT FROM (payload ->> 'opened') AND "opened__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "opened__tok" THEN 'null_token' END, CASE WHEN "opened__sen" THEN 'sentinel:' || "opened__c" END, CASE WHEN "opened__m" IS DISTINCT FROM "opened__v" AND "opened__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "opened__unm" THEN 'unmapped' END, CASE WHEN "opened__bad" THEN 'unparseable' END, CASE WHEN "opened__oor" THEN 'out_of_range' END), 'closed', silver.flags(CASE WHEN "closed__c" IS DISTINCT FROM (payload ->> 'closed') AND "closed__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "closed__tok" THEN 'null_token' END, CASE WHEN "closed__sen" THEN 'sentinel:' || "closed__c" END, CASE WHEN "closed__m" IS DISTINCT FROM "closed__v" AND "closed__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "closed__unm" THEN 'unmapped' END, CASE WHEN "closed__bad" THEN 'unparseable' END, CASE WHEN "closed__oor" THEN 'out_of_range' END), 'amount', silver.flags(CASE WHEN "amount__c" IS DISTINCT FROM (payload ->> 'amount') AND "amount__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "amount__tok" THEN 'null_token' END, CASE WHEN "amount__sen" THEN 'sentinel:' || "amount__c" END, CASE WHEN "amount__m" IS DISTINCT FROM "amount__v" AND "amount__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "amount__unm" THEN 'unmapped' END, CASE WHEN "amount__bad" THEN 'unparseable' END, CASE WHEN "amount__oor" THEN 'out_of_range' END), 'flag', silver.flags(CASE WHEN "flag__c" IS DISTINCT FROM (payload ->> 'flag') AND "flag__c" IS NOT NULL THEN 'cleaned' END, CASE WHEN "flag__tok" THEN 'null_token' END, CASE WHEN "flag__sen" THEN 'sentinel:' || "flag__c" END, CASE WHEN "flag__m" IS DISTINCT FROM "flag__v" AND "flag__m" IS NOT NULL THEN 'mapped' END, CASE WHEN "flag__unm" THEN 'unmapped' END, CASE WHEN "flag__bad" THEN 'unparseable' END, CASE WHEN "flag__oor" THEN 'out_of_range' END))) AS _quality_flags, array_remove(ARRAY[CASE WHEN "id__bad" THEN 'id:unparseable' END, CASE WHEN "id__oor" THEN 'id:out_of_range' END, CASE WHEN "id" IS NULL THEN 'id:required_missing' END, CASE WHEN "state__bad" THEN 'state:unparseable' END, CASE WHEN "state__oor" THEN 'state:out_of_range' END, CASE WHEN "state__unm" THEN 'state:unmapped' END, CASE WHEN "opened__bad" THEN 'opened:unparseable' END, CASE WHEN "opened__oor" THEN 'opened:out_of_range' END, CASE WHEN "closed__bad" THEN 'closed:unparseable' END, CASE WHEN "closed__oor" THEN 'closed:out_of_range' END, CASE WHEN "amount__bad" THEN 'amount:unparseable' END, CASE WHEN "amount__oor" THEN 'amount:out_of_range' END, CASE WHEN "flag__bad" THEN 'flag:unparseable' END, CASE WHEN "flag__oor" THEN 'flag:out_of_range' END]::text[], NULL) AS _errors, false AS _rejected, NULL::text AS _duplicate_of FROM (SELECT * FROM (SELECT *, CASE WHEN "id__oor" THEN NULL ELSE "id__t" END AS "id", CASE WHEN "state__oor" THEN NULL ELSE "state__t" END AS "state", CASE WHEN "opened__oor" THEN NULL ELSE "opened__t" END AS "opened", CASE WHEN "closed__oor" THEN NULL ELSE "closed__t" END AS "closed", CASE WHEN "amount__oor" THEN NULL ELSE "amount__t" END AS "amount", CASE WHEN "flag__oor" THEN NULL ELSE "flag__t" END AS "flag" FROM (SELECT *, "id__m" AS "id__t", ("id__m" IS NOT NULL AND "id__m" IS NULL) AS "id__bad", false AS "id__oor", "state__m" AS "state__t", ("state__m" IS NOT NULL AND "state__m" IS NULL) AS "state__bad", false AS "state__oor", (coalesce(silver.try_ts("opened__m",  E'\\d{4}-\\d{1,2}-\\d{1,2}', 'YYYY-MM-DD'), silver.try_ts("opened__m",  E'(\\d{1,2})/(\\d{1,2})/\\d{4}', 'MM/DD/YYYY')))::date AS "opened__t", ("opened__m" IS NOT NULL AND (coalesce(silver.try_ts("opened__m",  E'\\d{4}-\\d{1,2}-\\d{1,2}', 'YYYY-MM-DD'), silver.try_ts("opened__m",  E'(\\d{1,2})/(\\d{1,2})/\\d{4}', 'MM/DD/YYYY')))::date IS NULL) AS "opened__bad", false AS "opened__oor", (coalesce(silver.try_ts("closed__m",  E'\\d{4}-\\d{1,2}-\\d{1,2}', 'YYYY-MM-DD'), silver.try_ts("closed__m",  E'(\\d{1,2})/(\\d{1,2})/\\d{4}', 'MM/DD/YYYY')))::date AS "closed__t", ("closed__m" IS NOT NULL AND (coalesce(silver.try_ts("closed__m",  E'\\d{4}-\\d{1,2}-\\d{1,2}', 'YYYY-MM-DD'), silver.try_ts("closed__m",  E'(\\d{1,2})/(\\d{1,2})/\\d{4}', 'MM/DD/YYYY')))::date IS NULL) AS "closed__bad", false AS "closed__oor", silver.try_numeric("amount__m") AS "amount__t", ("amount__m" IS NOT NULL AND silver.try_numeric("amount__m") IS NULL) AS "amount__bad", false AS "amount__oor", silver.try_bool("flag__m", ARRAY['yes']::text[], ARRAY['no']::text[]) AS "flag__t", ("flag__m" IS NOT NULL AND silver.try_bool("flag__m", ARRAY['yes']::text[], ARRAY['no']::text[]) IS NULL) AS "flag__bad", false AS "flag__oor" FROM (SELECT *, CASE WHEN "id__tok" OR "id__sen" THEN NULL ELSE "id__c" END AS "id__v", CASE WHEN "id__tok" OR "id__sen" THEN NULL ELSE "id__c" END AS "id__m", false AS "id__unm", CASE WHEN "state__tok" OR "state__sen" THEN NULL ELSE "state__c" END AS "state__v", CASE silver.norm_key(CASE WHEN "state__tok" OR "state__sen" THEN NULL ELSE "state__c" END) WHEN 'open' THEN 'open' WHEN 'inprogress' THEN 'in_progress' WHEN 'closed' THEN 'closed' ELSE NULL END AS "state__m", (CASE WHEN "state__tok" OR "state__sen" THEN NULL ELSE "state__c" END IS NOT NULL AND NOT coalesce(silver.norm_key(CASE WHEN "state__tok" OR "state__sen" THEN NULL ELSE "state__c" END) = ANY(ARRAY['open', 'inprogress', 'closed']::text[]), false)) AS "state__unm", CASE WHEN "opened__tok" OR "opened__sen" THEN NULL ELSE "opened__c" END AS "opened__v", CASE WHEN "opened__tok" OR "opened__sen" THEN NULL ELSE "opened__c" END AS "opened__m", false AS "opened__unm", CASE WHEN "closed__tok" OR "closed__sen" THEN NULL ELSE "closed__c" END AS "closed__v", CASE WHEN "closed__tok" OR "closed__sen" THEN NULL ELSE "closed__c" END AS "closed__m", false AS "closed__unm", CASE WHEN "amount__tok" OR "amount__sen" THEN NULL ELSE "amount__c" END AS "amount__v", CASE WHEN "amount__tok" OR "amount__sen" THEN NULL ELSE "amount__c" END AS "amount__m", false AS "amount__unm", CASE WHEN "flag__tok" OR "flag__sen" THEN NULL ELSE "flag__c" END AS "flag__v", CASE WHEN "flag__tok" OR "flag__sen" THEN NULL ELSE "flag__c" END AS "flag__m", false AS "flag__unm" FROM (SELECT *, false AS "id__tok", false AS "id__sen", false AS "state__tok", false AS "state__sen", false AS "opened__tok", false AS "opened__sen", false AS "closed__tok", false AS "closed__sen", coalesce(lower("amount__c") = ANY(ARRAY['n/a']::text[]), false) AS "amount__tok", coalesce("amount__c" = ANY(ARRAY['999']::text[]) OR silver.try_numeric("amount__c") = ANY(ARRAY[999.0]::numeric[]), false) AS "amount__sen", false AS "flag__tok", false AS "flag__sen" FROM (SELECT *, silver.blank_to_null(regexp_replace((payload ->> 'id'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g')) AS "id__c", silver.blank_to_null(regexp_replace((payload ->> 'state'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g')) AS "state__c", silver.blank_to_null(regexp_replace((payload ->> 'opened'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g')) AS "opened__c", silver.blank_to_null(regexp_replace((payload ->> 'closed'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g')) AS "closed__c", silver.blank_to_null(btrim(regexp_replace(regexp_replace((payload ->> 'amount'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g'), '[$₹€£¥]|\m(usd|eur|inr|gbp|jpy)\M', '', 'gi'))) AS "amount__c", silver.blank_to_null(regexp_replace((payload ->> 'flag'), '^[[:space:]\u00a0]+|[[:space:]\u00a0]+$', '', 'g')) AS "flag__c" FROM (SELECT bronze_id, row_hash, payload FROM bronze.records WHERE run_id = %(run_id)s AND parse_status = 'ok') AS "s1") AS "s2") AS "s3") AS "s4") AS "s5") AS "s6") AS s7) AS s8
